changeSet.sql:
DELETE FROM knowledge.knowledge_source_endpoint k USING knowledge.app_endpoint e WHERE k.endpoint_id = e.id AND k.role = 'store_to' AND (e.status <> 'active' OR e.kind <> 'object_store');
DELETE FROM knowledge.knowledge_source_endpoint WHERE role = 'tech_stack';
UPDATE knowledge.wf_exec_log w SET store_to_endpoint_ids = ARRAY( SELECT unnest(w.store_to_endpoint_ids) INTERSECT SELECT e.id FROM knowledge.app_endpoint e WHERE e.status = 'active' AND e.kind = 'object_store' ), tech_stack_endpoint_ids = '{}'::uuid[], updated_at = NOW();
